<script setup lang="ts">import type { RatingAccount } from '../stores/app'; import UserAvatar from './UserAvatar.vue'; const p=defineProps<{ item: RatingAccount & { nickname?: string; avatar_url?: string }; rank: number }>(); function rate(){return p.item.rated_matches?Math.round(p.item.wins/p.item.rated_matches*100):0}</script>
<template><view class="rating-row"><text :class="['rank', { medal: rank <= 3 }]">{{ rank }}</text><UserAvatar size="sm" :name="item.nickname || '球友'" :src="item.avatar_url"/><view class="main"><text class="name">{{ item.nickname || `球友 ${item.user_id.slice(0, 5)}` }}</text><text class="meta">{{ item.rated_matches }}场 · 胜率{{ rate() }}%</text></view><text class="score">{{ item.current_rating }}</text></view></template>
<style scoped>.rating-row{display:flex;min-height:3.75rem;align-items:center;gap:.7rem;border-bottom:1px solid #e7e9e7}.rating-row:last-child{border-bottom:0}.rank{width:1.25rem;color:#7b837f;text-align:center;font-size:.8125rem;font-weight:700}.rank.medal{color:#9a7a1c}.main{min-width:0;flex:1}.name{display:block;font-size:.9rem;font-weight:700}.meta{display:block;margin-top:.15rem;color:#7b837f;font-size:.75rem}.score{font-size:1rem;font-weight:800}</style>
